        c = _c;
    }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}();

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint creditBefore = c.credit(address(this));

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint creditAfter = c.credit(address(this));

        assert(
            !reverted &&
            creditBefore == amount &&
            creditAfter == 0 &&
            beforeC >= amount &&
            beforeC - afterC == amount &&
            afterThis - beforeThis == amount
        );
    }

    receive() external payable {}
}

